contracts/v3/interfaces/IArcNSBaseRegist.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "./IArcNSRegistry.sol";

/// @title IArcNSBaseRegistrar
/// @notice Interface for the ArcNS base registrar — implements EIP-721 pattern for domain names
interface IArcNSBaseRegistrar {
    /// @notice Emitted when a controller is added
    event ControllerAdded(address indexed controller);

    /// @notice Emitted when a controller is removed
    event ControllerRemoved(address indexed controller);

    /// @notice Emitted when a name is registered
    event NameRegistered(uint256 indexed id, address indexed owner, uint256 expires);

    /// @notice Emitted when a name is renewed
    event NameRenewed(uint256 indexed id, uint256 expires);

    /// @notice Adds a controller that can register and renew names
    /// @param controller The controller address to add
    function addController(address controller) external;

    /// @notice Removes a controller
    /// @param controller The controller address to remove
    function removeController(address controller) external;

    /// @notice Returns the canonical ArcNS registry used by this registrar
    function registry() external view returns (IArcNSRegistry);

    /// @notice Registers a new name
    /// @param id The token ID (labelhash)
    /// @param owner_ The owner of the new name
    /// @param duration Registration duration in seconds
    /// @return expiry The expiry timestamp
    function register(uint256 id, address owner_, uint256 duration) external returns (uint256);

    /// @notice Registers a new name and sets a resolver atomically
    /// @param id The token ID (labelhash)
    /// @param owner_ The owner of the new name
    /// @param duration Registration duration in seconds
    /// @param resolver_ The resolver address to set
    /// @return expiry The expiry timestamp
    function registerWithResolver(uint256 id, address owner_, uint256 duration, address resolver_) external returns (uint256);

    /// @notice Renews an existing name
    /// @param id The token ID (labelhash)
    /// @param duration Additional duration in seconds
    /// @return expiry The new expiry timestamp
    function renew(uint256 id, uint256 duration) external returns (uint256);

    /// @notice Returns whether a name is available for registration
    /// @param id The token ID (labelhash)
    /// @return True if the name is available
    function available(uint256 id) external view returns (bool);

    /// @notice Returns the expiry timestamp for a token ID
    /// @param id The token ID (labelhash)
    /// @return The expiry timestamp (0 if never registered)
    function nameExpires(uint256 id) external view returns (uint256);

    /// @notice Returns the human-readable TLD string (e.g. "arc")
    /// @return The TLD string
    function tld() external view returns (string memory);

    /// @notice Returns the namehash of the TLD node this registrar owns
    /// @return The base node hash
    function baseNode() external view returns (bytes32);

    /// @notice Allows the NFT owner to reclaim registry ownership of their name
    /// @param id The token ID (labelhash)
    /// @param owner_ The address to set as registry owner
    function reclaim(uint256 id, address owner_) external;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "./IArcNSBaseRegistrar.sol";

/// @title IArcNSBaseRegistrarV2
/// @notice Label-aware registrar interface used by the mainnet metadata migration.
interface IArcNSBaseRegistrarV2 is IArcNSBaseRegistrar {
    function metadataVersion() external pure returns (uint256);

    function labelOf(uint256 id) external view returns (string memory);

    function registerWithLabel(
        uint256 id,
        string calldata label,
        address owner_,
        uint256 duration
    ) external returns (uint256);

    function registerWithResolverAndLabel(
        uint256 id,
        string calldata label,
        address owner_,
        uint256 duration,
        address resolver_
    ) external returns (uint256);
}

contracts/v3/interfaces/IArcNSController.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "./IArcNSPriceOracle.sol";

/// @title IArcNSController
/// @notice Interface for the ArcNS Controller — commit-reveal registration and renewal
interface IArcNSController {
    /// @notice Submits a commitment hash to begin the commit-reveal flow
    /// @param commitment The commitment hash (from makeCommitment)
    function commit(bytes32 commitment) external;

    /// @notice Registers a name after a valid commitment has matured
    /// @param name_ The plaintext label to register
    /// @param owner_ The address that will own the name
    /// @param duration Registration duration in seconds
    /// @param secret The secret used in the commitment
    /// @param resolverAddr The resolver address (address(0) to skip resolver setup)
    /// @param reverseRecord Whether to set a reverse record for owner_
    /// @param maxCost Maximum USDC cost the caller is willing to pay (6 decimals)
    function register(
        string calldata name_,
        address owner_,
        uint256 duration,
        bytes32 secret,
        address resolverAddr,
        bool reverseRecord,
        uint256 maxCost
    ) external;

    function registerWithDiscount(
        string calldata name_,
        address owner_,
        uint256 duration,
        bytes32 secret,
        address resolverAddr,
        bool reverseRecord,
        uint256 maxCost,
        bytes32[] calldata proof
    ) external;

    function discountRentPrice(string memory name_, uint256 duration) external view returns (IArcNSPriceOracle.Price memory);

    /// @notice Renews an existing name
    /// @param name_ The plaintext label to renew
    /// @param duration Additional duration in seconds
    /// @param maxCost Maximum USDC cost the caller is willing to pay (6 decimals)
    function renew(string calldata name_, uint256 duration, uint256 maxCost) external;

    /// @notice Returns the rent price for a name and duration
    /// @param name_ The plaintext label
    /// @param duration Duration in seconds
    /// @return Price struct with base and premium components
    function rentPrice(string memory name_, uint256 duration) external view returns (IArcNSPriceOracle.Price memory);

    /// @notice Returns whether a name is available for registration
    /// @param name_ The plaintext label
    /// @return True if the name is valid and available
    function available(string memory name_) external view returns (bool);

    /// @notice Computes the commitment hash binding to a specific sender
    /// @param name_ The plaintext label
    /// @param owner_ The intended owner
    /// @param duration Registration duration in seconds
    /// @param secret The secret value
    /// @param resolverAddr The resolver address
    /// @param reverseRecord Whether to set a reverse record
    /// @param sender The sender address (pass msg.sender from the frontend)
    /// @return The commitment hash
    function makeCommitment(
        string memory name_,
        address owner_,
        uint256 duration,
        bytes32 secret,
        address resolverAddr,
        bool reverseRecord,
        address sender
    ) external pure returns (bytes32);

    /// @notice Returns the status of a commitment
    /// @param commitment The commitment hash
    /// @return timestamp When the commitment was made (0 if not found)
    /// @return exists Whether the commitment exists
    /// @return matured Whether MIN_COMMITMENT_AGE has passed
    /// @return expired_ Whether MAX_COMMITMENT_AGE has passed
    function getCommitmentStatus(bytes32 commitment) external view returns (
        uint256 timestamp,
        bool exists,
        bool matured,
        bool expired_
    );

    /// @notice Updates the reverseRegistrar address (ADMIN_ROLE required)
    /// @dev Required for clean migration when ArcNSReverseRegistrar is redeployed.
    ///      Rejects address(0). Emits ReverseRegistrarUpdated.
    /// @param newReverseRegistrar The new ArcNSReverseRegistrar contract address
    function setReverseRegistrar(address newReverseRegistrar) external;

    /// @notice Switches the controller to a label-aware V2 base registrar.
    /// @dev ADMIN_ROLE required and the controller must be paused.
    function setBaseRegistrar(address newBaseRegistrar) external;

    function setDiscountRegistry(address newDiscountRegistry) external;
}

