// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title IArcNSPriceOracle
/// @notice Returns registration/renewal prices in USDC (6 decimals)
interface IArcNSPriceOracle {
    /// @notice Price breakdown for a registration or renewal
    struct Price {
        uint256 base;    // base price in USDC (6 decimals)
        uint256 premium; // premium for recently expired names (linear decay)
    }

    /// @notice Returns the price for registering or renewing a name
    /// @param name The plaintext label (e.g. "alice")
    /// @param expires Current expiry timestamp (0 if new name, never registered)
    /// @param duration Registration duration in seconds
    /// @return Price struct with base and premium components
    function price(
        string calldata name,
        uint256 expires,
        uint256 duration
    ) external view returns (Price memory);
}

contracts/v3/interfaces/IArcNSRegistry.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title IArcNSRegistry
/// @notice Core registry interface — implements EIP-137 pattern
interface IArcNSRegistry {
    /// @notice Emitted when a node's owner changes via setSubnodeOwner or setSubnodeRecord
    event NewOwner(bytes32 indexed node, bytes32 indexed label, address owner);

    /// @notice Emitted when a node's owner changes via setOwner or setRecord
    event Transfer(bytes32 indexed node, address owner);

    /// @notice Emitted when a node's resolver changes
    event NewResolver(bytes32 indexed node, address resolver);

    /// @notice Emitted when a node's TTL changes
    event NewTTL(bytes32 indexed node, uint64 ttl);

    /// @notice Emitted when an operator approval changes
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);

    /// @notice Sets the owner, resolver, and TTL for a node atomically
    /// @param node The node to update
    /// @param owner_ The new owner address
    /// @param resolver_ The new resolver address
    /// @param ttl_ The new TTL value
    function setRecord(bytes32 node, address owner_, address resolver_, uint64 ttl_) external;

    /// @notice Creates or updates a subnode, setting owner, resolver, and TTL atomically
    /// @param node The parent node
    /// @param label The label hash of the subnode
    /// @param owner_ The new owner of the subnode
    /// @param resolver_ The resolver for the subnode
    /// @param ttl_ The TTL for the subnode
    function setSubnodeRecord(bytes32 node, bytes32 label, address owner_, address resolver_, uint64 ttl_) external;

    /// @notice Creates or updates a subnode, returning the subnode hash
    /// @param node The parent node
    /// @param label The label hash of the subnode
    /// @param owner_ The new owner of the subnode
    /// @return The subnode hash
    function setSubnodeOwner(bytes32 node, bytes32 label, address owner_) external returns (bytes32);

    /// @notice Sets the resolver for a node
    /// @param node The node to update
    /// @param resolver_ The new resolver address
    function setResolver(bytes32 node, address resolver_) external;

    /// @notice Transfers ownership of a node
    /// @param node The node to transfer
    /// @param owner_ The new owner address
    function setOwner(bytes32 node, address owner_) external;

    /// @notice Sets the TTL for a node
    /// @param node The node to update
    /// @param ttl_ The new TTL value
    function setTTL(bytes32 node, uint64 ttl_) external;

    /// @notice Enables or disables approval for an operator to manage all of the caller's nodes
    /// @param operator The operator address
    /// @param approved Whether to approve or revoke
    function setApprovalForAll(address operator, bool approved) external;

    /// @notice Returns the owner of a node
    /// @param node The node to query
    /// @return The owner address
    function owner(bytes32 node) external view returns (address);

    /// @notice Returns the resolver for a node
    /// @param node The node to query
    /// @return The resolver address
    function resolver(bytes32 node) external view returns (address);

    /// @notice Returns the TTL for a node
    /// @param node The node to query
    /// @return The TTL value
    function ttl(bytes32 node) external view returns (uint64);

    /// @notice Returns whether a record exists for a node
    /// @param node The node to query
    /// @return True if the node has a non-zero owner
    function recordExists(bytes32 node) external view returns (bool);

    /// @notice Returns whether an operator is approved for an owner
    /// @param owner_ The owner address
    /// @param operator The operator address
    /// @return True if approved
    function isApprovedForAll(address owner_, address operator) external view returns (bool);
}

contracts/v3/interfaces/IArcNSResolver.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title IArcNSResolver
/// @notice Interface for the ArcNS Resolver — implements EIP-137 pattern for record resolution
interface IArcNSResolver {
    /// @notice Sets the EVM address record for a node (coin type 60)
    /// @param node The namehash of the node
    /// @param a The EVM address to associate with the node
    function setAddr(bytes32 node, address a) external;

    /// @notice Returns the EVM address record for a node (coin type 60)
    /// @param node The namehash of the node
    /// @return The EVM address associated with the node
    function addr(bytes32 node) external view returns (address payable);

    /// @notice Sets the name record for a node — internal use only via CONTROLLER_ROLE
    /// @dev Not part of the v1 public interface. Used exclusively by ReverseRegistrar.
    /// @param node The namehash of the node
    /// @param name_ The name string to store
    function setName(bytes32 node, string calldata name_) external;

    /// @notice Returns the name record for a node — used for reverse resolution
    /// @param node The namehash of the node
    /// @return The name string associated with the node
    function name(bytes32 node) external view returns (string memory);

    /// @notice Grants or revokes CONTROLLER_ROLE for an address
    /// @param controller The address to grant or revoke
    /// @param trusted Whether to grant (true) or revoke (false)
    function setController(address controller, bool trusted) external;
}

contracts/v3/interfaces/IArcNSReverseReg.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title IArcNSReverseRegistrar
/// @notice Interface for the ArcNS Reverse Registrar — manages addr.reverse records
interface IArcNSReverseRegistrar {
    /// @notice Sets the reverse record for an address — called by Controller at registration time
    /// @param addr_ The address to set the reverse record for
    /// @param name_ The full domain name (e.g. "alice.arc")
    function setReverseRecord(address addr_, string calldata name_) external;

    /// @notice Sets the primary name for the caller's address (dashboard-driven flow)
    /// @param name_ The full domain name to set as primary (e.g. "alice.arc")
    /// @return reverseNode The reverse node hash
    function setName(string calldata name_) external returns (bytes32);

    /// @notice Claims the reverse node for an address with a specific resolver
    /// @param addr_ The address to claim for
    /// @param owner_ The owner to assign to the reverse node
    /// @param resolver_ The resolver to assign to the reverse node
    /// @return The reverse node hash
    function claimWithResolver(address addr_, address owner_, address resolver_) external returns (bytes32);

    /// @notice Returns the reverse node hash for an address
    /// @param addr_ The address to compute the reverse node for
    /// @return The reverse node hash
    function node(address addr_) external pure returns (bytes32);
}

